import{_ as e,c as o,o as d,ae as r}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Product Type Sub-Resources (Product Types tag)","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-variants","title":"Variants — for a configurable product","description":"List the child variant products of a configurable parent. Each variant is a `simple` product with the same card-level fields as the listing endpoint.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/23/variants\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 24,\\n    \\"sku\\": \\"LUGGAGE-RED\\",\\n    \\"type\\": \\"simple\\",\\n    \\"name\\": \\"Luggage bags-Red\\",\\n    \\"price\\": 100,\\n    \\"formattedPrice\\": \\"$100.00\\",\\n    \\"...\\": \\"...\\"\\n  }\\n]\\n","commonErrors":[{"error":"404 Not Found","cause":"Parent product `{productId}` doesn\'t exist or isn\'t configurable","solution":"Use `GET /api/shop/products?type=configurable` to find configurable products."}]},{"id":"list-booking-products","title":"Booking Products — config for a product","description":"Booking-specific configuration row(s) for a `booking`-type product. The `type` field on each row tells you which slot helper drives availability — pair it with [Booking Slots](/api/rest-api/shop/products/get-booking-slots) for a date.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2507/booking-products\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"type\\": \\"default\\",\\n    \\"qty\\": 150,\\n    \\"location\\": \\"Noida, Uttar Pradesh\\",\\n    \\"showLocation\\": 0,\\n    \\"availableFrom\\": \\"2026-04-06T12:00:00+05:30\\",\\n    \\"availableTo\\": \\"2026-12-31T12:00:00+05:30\\",\\n    \\"createdAt\\": \\"2026-04-03T00:24:30+05:30\\",\\n    \\"updatedAt\\": \\"2026-04-06T21:09:47+05:30\\",\\n    \\"slots\\": {\\n      \\"bookingType\\": \\"one\\",\\n      \\"sameSlotAllDays\\": null,\\n      \\"slots\\": [\\n        { \\"id\\": \\"1\\", \\"from\\": \\"12:00\\", \\"to\\": \\"18:00\\", \\"from_day\\": \\"1\\", \\"to_day\\": \\"1\\" },\\n        { \\"id\\": \\"2\\", \\"from\\": \\"12:00\\", \\"to\\": \\"18:00\\", \\"from_day\\": \\"2\\", \\"to_day\\": \\"2\\" }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"get-booking-product","title":"Booking Products — single by ID","description":"Fetch a single booking config row by its global ID (the value found in `bookingProducts[].id` on the parent product). Includes IRI references to the type-specific slot config.\\n","request":"curl -X GET \\"http://localhost/api/shop/booking-products/1\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 1,\\n  \\"type\\": \\"default\\",\\n  \\"qty\\": 150,\\n  \\"location\\": \\"Noida, Uttar Pradesh\\",\\n  \\"showLocation\\": 0,\\n  \\"availableEveryWeek\\": null,\\n  \\"availableFrom\\": \\"2026-04-06T12:00:00+05:30\\",\\n  \\"availableTo\\": \\"2026-12-31T12:00:00+05:30\\",\\n  \\"slots\\": { \\"bookingType\\": \\"one\\", \\"slots\\": [ \\"...\\" ] },\\n  \\"defaultSlot\\": \\"/api/shop/booking_product_default_slots/1\\",\\n  \\"appointmentSlot\\": null,\\n  \\"rentalSlot\\": null,\\n  \\"tableSlot\\": null,\\n  \\"eventTickets\\": []\\n}\\n"},{"id":"get-booking-default-slot","title":"Booking Slot Config — `default` type","description":"Static slot configuration for a `default`-type booking product. The `slots` field is a **JSON string** — parse it client-side. For runtime availability on a specific date, use [Booking Slots](/api/rest-api/shop/products/get-booking-slots).\\n","request":"curl -X GET \\"http://localhost/api/shop/booking_product_default_slots/1\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 1,\\n  \\"bookingType\\": \\"one\\",\\n  \\"duration\\": null,\\n  \\"breakTime\\": null,\\n  \\"slots\\": \\"[{\\\\\\"id\\\\\\": \\\\\\"1\\\\\\", \\\\\\"to\\\\\\": \\\\\\"18:00\\\\\\", \\\\\\"from\\\\\\": \\\\\\"12:00\\\\\\", \\\\\\"to_day\\\\\\": \\\\\\"1\\\\\\", \\\\\\"from_day\\\\\\": \\\\\\"1\\\\\\"}]\\"\\n}\\n"},{"id":"get-booking-event-ticket","title":"Booking Slot Config — `event` ticket","description":"Single ticket row for an `event`-type booking product. Each ticket is its own purchasable line with its own price, qty, and locale-specific `name` / `description`.\\n","request":"curl -X GET \\"http://localhost/api/shop/booking_product_event_tickets/7\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 7,\\n  \\"bookingProductId\\": 2,\\n  \\"price\\": 120,\\n  \\"qty\\": 1500,\\n  \\"specialPrice\\": 115,\\n  \\"specialPriceFrom\\": \\"2026-04-06 12:00:00\\",\\n  \\"specialPriceTo\\": \\"2026-04-30 12:00:00\\",\\n  \\"formattedPrice\\": \\"$120.00\\",\\n  \\"formattedSpecialPrice\\": \\"$115.00\\",\\n  \\"translations\\": [\\"/api/booking_product_event_ticket_translations/7\\"],\\n  \\"translation\\": \\"/api/booking_product_event_ticket_translations/7\\"\\n}\\n"},{"id":"list-bundle-options","title":"Bundle Options — for a bundle product","description":"Decision groups for a `bundle`-type product. Each option has its member products as IRIs (under `bundleOptionProducts[]`) — dereference for full member details.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2517/bundle-options\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"type\\": \\"radio\\",\\n    \\"isRequired\\": 1,\\n    \\"sortOrder\\": 0,\\n    \\"product\\": \\"/api/shop/products/2517\\",\\n    \\"bundleOptionProducts\\": [\\"/api/shop/product-bundle-option-products/1\\"],\\n    \\"translation\\": \\"/api/shop/product_bundle_option_translations/1\\",\\n    \\"translations\\": [\\n      \\"/api/shop/product_bundle_option_translations/5\\",\\n      \\"/api/shop/product_bundle_option_translations/1\\"\\n    ]\\n  }\\n]\\n"},{"id":"list-bundle-option-products","title":"Bundle Option Products","description":"Member products inside a bundle option (the actual SKUs the customer can pick). Each row links back to its parent `bundleOption` and its `product`.\\n","request":"curl -X GET \\"http://localhost/api/shop/product-bundle-option-products?per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 12\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 6\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"qty\\": 1,\\n    \\"isUserDefined\\": 1,\\n    \\"isDefault\\": 1,\\n    \\"sortOrder\\": 0,\\n    \\"bundleOption\\": \\"/api/shop/product_bundle_options/1\\",\\n    \\"product\\": \\"/api/shop/products/2512\\"\\n  }\\n]\\n"},{"id":"list-grouped-products","title":"Grouped Products — members of a grouped product","description":"Associated products inside a `grouped`-type product. The customer can add any subset to the cart with their own quantities.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2516/grouped-products\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  { \\"id\\": 1, \\"qty\\": 1, \\"sortOrder\\": 0, \\"product\\": \\"/api/shop/products/2516\\", \\"associatedProduct\\": \\"/api/shop/products/2512\\" },\\n  { \\"id\\": 2, \\"qty\\": 1, \\"sortOrder\\": 1, \\"product\\": \\"/api/shop/products/2516\\", \\"associatedProduct\\": \\"/api/shop/products/2514\\" }\\n]\\n"},{"id":"list-downloadable-links","title":"Downloadable Links — for a downloadable product","description":"Purchasable downloadable links attached to a `downloadable`-type product. Each link carries its own price, sample file, and download limit.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2506/downloadable-links\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 2,\\n    \\"url\\": \\"https://example.com/textbook.pdf\\",\\n    \\"type\\": \\"url\\",\\n    \\"price\\": 69,\\n    \\"sampleFile\\": \\"product_downloadable_links/2506/...pdf\\",\\n    \\"sampleFileName\\": \\"Personal Finance.pdf\\",\\n    \\"sampleType\\": \\"file\\",\\n    \\"downloads\\": 10,\\n    \\"sortOrder\\": 0,\\n    \\"createdAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"updatedAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"formattedPrice\\": \\"$69.00\\",\\n    \\"fileUrl\\": \\"http://localhost/storage/\\",\\n    \\"sampleFileUrl\\": \\"http://localhost/api/downloadable/download-sample/link/2\\",\\n    \\"product\\": \\"/api/shop/products/2506\\",\\n    \\"translation\\": \\"/api/shop/product_downloadable_link_translations/2\\",\\n    \\"translations\\": [\\n      \\"/api/shop/product_downloadable_link_translations/2\\",\\n      \\"/api/shop/product_downloadable_link_translations/3\\"\\n    ]\\n  }\\n]\\n"},{"id":"list-downloadable-samples","title":"Downloadable Samples — for a downloadable product","description":"Free preview files attached to a downloadable product. Listed separately from the paid links so the customer can preview before buying.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2506/downloadable-samples\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"file\\": \\"product_downloadable_links/2506/....pdf\\",\\n    \\"fileName\\": \\"document.pdf\\",\\n    \\"type\\": \\"file\\",\\n    \\"sortOrder\\": 0,\\n    \\"createdAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"updatedAt\\": \\"2026-04-03T00:14:55+05:30\\",\\n    \\"fileUrl\\": \\"http://localhost/api/downloadable/download-sample/sample/1\\",\\n    \\"product\\": \\"/api/shop/products/2506\\",\\n    \\"translation\\": \\"/api/shop/product_downloadable_sample_translations/1\\",\\n    \\"translations\\": [\\"/api/shop/product_downloadable_sample_translations/1\\"]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/shop/products/product-type-subresources.md","filePath":"api/rest-api/shop/products/product-type-subresources.md"}'),a={name:"api/rest-api/shop/products/product-type-subresources.md"};function n(i,t,s,c,l,p){return d(),o("div",null,t[0]||(t[0]=[r("",44)]))}const b=e(a,[["render",n]]);export{h as __pageData,b as default};
